    (1, 50, "ወወህበሙ ሙሴ ወ'እት መርቀቅ ቤሕቫሆሙ ለአለ: ፈቻ ፈዱ ለዜሮን ወለደቁቱ በቃለ እግዚአብሔር በከመ አዛዘ ኣግዚአብሔር ለሙሴ።"),
