    (13, 14, "ask ዓማ ንጉሠ በለን ወቱቀበሎሙ ምስለ ዙሉ ሕኻቡ\" ከመ '[ ይትቃተሎሙ በአድራይን = ወይቈሎ እግዚኣብሔር ለሙሌ ጴትፍርሆ, እስመ ውስተ እክ አንብ።"),
    (
        13,
        15,
        "ወለሉ ሕኝቡ ወለዙሉ ምድሩ ወትገዳር ከመ ንበርካሁ ለሴዎን ንጉሠ ጸሞሬዎን ዘይነብር ውስት ሓሴበን = | ወቀተሎ ሎቴ ወለደቂቁ ወለሹዙሉ ሕዝቡ ኣስክ እያ - ችረፈ ሎቱ ነፏጺተ፡. ወጠረ ምድሮሙ።",
    ),
    (
        13,
        16,
        ". ምፅራፍ [ik ወግፀዙ ጄፍቅጥ እስራኤል መግደሩ መንገለ ዐረቢ ለሞ . አብ ኀበ ዮርጳጻኖስ ዘመንገለ ኢያሪክ = ወበበ ርእየ ባላቅ ወልደ ስፎር ሁሎ ዘገብሩ ጽል በአሞ ዎን ፈርህዎሙ ሞኣብ ለሕኘዃኘብ ጥቀ ኣስመ ብዙኃን አሙ ንቱ ወተህውዥዀ እምቅድመ ገጾሙ ለደቁቀ አስራኤል = ወዴቬቤሎሙ ሞአብ ለጸኣሩን ምድያም ፡ ይኣዚ ታሣል ቆሙ ዛቲ ት9ይንት ለሹሎሙ እለ ዐበውድነ ከመ ያልቅ ላሕም ሣስረ ዘውስተ ፣ጻም ፡ ወባዒቅ ወልደ ሰፎር ንጉሠ ልብ ውሕኣቱ በውሕክቴቱ መመል » 3, =f አሌ ላኪ ሞአብ አሣጐልዎሙ ሕዝቢ ክዋስ nN 5 ንብኡ ደፍቆሙስ ጸድሣንክሙ ወአዋልዲሕሙ TRE | 4በ ጴዎን ንጕሠ ኣሞሬዎን = i የኢትዮጵያ ኮርቶዶክስ ተዋሕዶ ቤት በ ከ n | i ' | - =; ወዘርእሙኒ ደም ጸሙ ኣም ሓሌቦን እስክ ዴን ወጻ. | 8፱ ax ጴመል ዋቲ ድሙ xara xምሮዑርጀ አሪት 'ዘጐልቀ፡ \" ም ወፈነወ ተናብልተ ሣበ በለዓም ወልፉ ቤር ዛዘፋቱራ ዘሀለወ ኀበ ፈለን ምድሮሙ ለደቁቀ ሕዝቡ።",
    ),
    (13, 17, '- ወጻውፆ እንዛ ድብል፡ ናሁ ሕዝብ ዛወዕክ እምግብጽ ከደና"ለገጹ ምድር ወሀለዉ ይነብሩ ቅሩ ብየ።'),
    (
        13,
        18,
        'ወይእዚኒ ነዓ ርግሞሙ ሊቷ እስመ ይጸንዑ እምኔየ Lr ጸአምር ከመ ዛአንተ በረከ ቡሩክ ይከውን ወዘጸንተ ረገ ምክ ርጉመ’ ይከውን =." " ወሐሩ እአዕሩን ሞአብ. ወኣፀሯንገ ምድያም ፡ ወነሥአ መቃስም ቲሆሙ ምስሌሆሙ ወበጽሕ 4በ ፡ በለዓም ወኔ. ርዎ ቃለ በላቃ።',
    ),
    (13, 19, '" ‘ወይቤሎሙ በ. ቱ Ly ሌሊተ ወአየድአክሙ i: ዘe | ቤጸኒ እግዚአብሔር መሣይደሩ መላእክት ሞአብ ግበ በለ ዓም።'),
    (13, 20, "ወመጽአ EE ግበ በለዓም ወይ ምንተ ' ይግበሩ መጽአ እሉ ሰብኣ “ሣቤክ።"),
    (13, 21, "ወይቤሎ በጻኝም ለአግዚአብሔር በላቅ ወልደ ሰፎር iy) ሞአብ ፈነዎው ኀቤዩ እንዘ ይብል።"),
    (13, 22, "- ናሁ ሕዝብ ዘወፅጮ፡ ኣምግብጽ ዘደንዋ ለገጸ ምድር ወሆለዉ. ንቡራነ ቅሩብየ ወይፅእሸቷ ነዐ ርግሞውሙ ሊተ ጳላመ እክል ቀቲሎቶሙ ወጸወፀአሙ ኣምድርዩ።"),
    (13, 23, "ወይቤሎ እግዚአብሔር ለበለዓም ኣትሑር ምስሌ ሆሙ ጠሏትርግሞሙ እስመ ቡሩክን ኣሙንቱ።"),
    (13, 24, ". ወተንሥአ በለዓም በጽባሕ ወፅቤሎሙ ለመላአክተ በጳሕቅ ሑሩ ሣበ እግዚእክሙ ግብኡ አስመ ኢሊ ነድ እግ እብሕሑር ከመ አሑር ምስሌክሙ።"),
    (
        13,
        25,
        "ወትንሥኡ መላክ ተ ሞአብ ወሖሩ ጎበ በላቅ ወይቤ ፡. ልዎ ጸባየ በለዓም መጺኣ ምኮሒን = ወደገመ ዓዲ በላቅ ወፈነወ መላእክተ ጸለ ይበኻኒቱ. ወኣለ ይክብሩ እምእልክ፡ = ወበጽሑ ሣበ በለንም ወይቤልዎ ክመዝ ይቤ ባላቅ ወልደ ፅፎር ብቍፀኒ አኢትትህክይ መጸ: ሣቤየ።",
    ),
    (
        13,
        26,
        "ኣስመ አክብሮ ክክብረክ ወሎ ዘትቤለ፤ እገብር ለክ ወነኝ ርግሞሙ ሊተ ለአሉ ሕዝብ = ወጸመወ-ሥአሙ፡ በለዓም ወሪቤሎሙ ለመላእክት ባላቅ ምልክ ቤት ወርቱ ወብሩረ ለኣመ ወህበኒ. ባላቅ ኢይክል ንኡ አው ተጻውሮ ቃለ እግዘአብሔር ከመ እግበር ሀያ. አምልብዩ።",
    ),
    (13, 27, "መዬአ፤ ሲቱ ዛተ ሌሊተ አንትሙ ምንተ ይገብር ኣግዚአብሔር ዘከመ ይቤ።"),
    (
        13,
        28,
        "ወመጽክ እግዚአብሔር\"ነ8 በለዓም “በዛቲ ሌሊት ወይ ቤሎ ከመ ይጸውዑከኑ መጽኡ እሉ ሰብኣ ተንሥሕ ወት ልዎሙ አሷ ቃስ ዘኣቤለክ ኪያሁ ተዓቀብ ለነቢ.ብ = ወተንሥኣ በለዓም ምስለ መላክክት ላሕ = መተትምፀ. መክተ አሣህ.አብሔር እስመ ወረ ውእቱ - መትንመአ መልኳክ ኣግቪክብጨር ያፅቅፎ ወወ አቋ ይዱ ቋሕ ወረ፣ ኣፍግማቶ ወረ’ . Rn ነ Ly isi iH EE ei Ly ቐቋ RE ኔ የኢትዮጵያ አኦርቶዶክስ. ተዋሕዶ ቤት EER RR BnO Ff . | አሪት ዘ'ልቀ፡ L) ዓን ዲበ አድግቱ ወክልኤቱ ደቂቁ ምስሌሁ።",
    ),
    (
        13,
        29,
        "ወሰበ ርእየቶ ይእቲ አድግት ለመልአክ እግዚአብሔር ድ ቀውም ውስተ ፍኖት ወሰይፍ ምሉሕ ውስተ እዴሁ ተግሣ ሠት ይእቲ አድጣት አምፍኖችት ወሐረች ውስተ ገዳም ወዛ a aሰኋጓ።",
    ),
    (13, 30, "ም ጳይኣቱ ምማት Hr ያማ ኣቕ ፍድውሕ L) ወቁመ መልአከ እአእግዚአብሒሔር ማእከለ ፀዬን ክዘዓፀደ ወይን ፡ ፀቂን ኣምለፌ ወፀቄን አምለፌ።"),
    (13, 31, "ወስበ ርአየቶ ይአቲ አድግት ለመልክክ እግዚአብር ተጠውቀት በፀቂን ወ መለጠወቶ ኣግሮ ለበለዓም ወደገመ ዘቢወታ።"),
    (13, 32, "ወደገመ ዓዲ መልአክ እግዚአብሔር ወሐረ ወቆመ ውስተ መክን ጸቢብ ግበ አልቦ ምግኃሥ አ. ለየማን ወኢ 'ለፀጋም።"),
    (13, 33, ". | ወሶበ ርእየቶ ይአቲ አድ ግት ለመልአከ አግዚአብሔር በረከት በታሕቱቴሁ ለበለዓም ወዛበጣ በበትር ለይአቲ እድግት።"),
    (14, 1, ") ወፈትሐ አግዚአብሔር አፉሃ ለይእቲ እድግት • ወት ቤሎ ለበለዓም ምንተ 'ረሰይኩክ ከመዝ ዘትዛዘብመኒ ናሁ ሣልስከ ዝንቱ።"),
    (
        14,
        2,
        "ወይቤላ በለዓም. ለይእቲ እድግት አስመ ተሣለቂ ላዕ ሴዩ ሶበሰ ብየ መጥበሕት ውስተ አዴየ እም ወዳእኩ እም ረገዝኩኪ = ወትቤሎ ይእቲ አድግት ለበለዓም እከኮኑ አነ ይእክቲ አድግትከ እንተ ትፄፀነኒ እምንእስክ አስክ ዮም ወእስከ ዛቲ ዕለት ፡ በኑ አመ ተፀውሮ ተፀወርኩክ ወገበርኩ ላፅ ሴከ ከመዝ ወይቤላ አልቦ።",
    ),
    (14, 3, "ወከሠተ እግዚአብሔር አዕይንቲሁ ለበለዓም ወርአዮ ለመልአክ አግዚአጸብሔር አንዘ ይቀውም ውስተ ፍኖት ፡ ወመጥበሕት ምልሕት ውስተ አዴሁ ወደነ፥ ወሰገደ ሎቱ በገጹ።"),
    (
        14,
        4,
        ") | '- ወይቤሎ መልአክ አግዚአብሔር ለምንት ዛበጥክሃ ልለ ድግትከ ወናሁ ሣልስክ ዝንቱ ወናሁ አነ መጻእኩ ከመ አዕቅፍክ እስመ ኢከነት ርትፅተ ፍኖትከ ቅድሜየ ፡ ወፅበ ርአዩየተኒ አድግትክ ተግሣሠት እምኔየ ናሁ ሣልስክ ዝንቱ = ለበሰ ኢተግኅሠት እምኔየ እም ወዳአኩ አምቁተልኩክ አዚ ፡ ወኪያሃሰ አም አጸሕየውክዊ * ወይቤሎ በለዓም ለመልአከ አግዚአብሔር አበስኩ አስመ ኢያእመርኩ ከመ አንተ ተቃወም ከኒ ቅድ ሟየ ውስተ ፍኖት ወይእዜኒ ለአመ ኢትፈቅድ እግባኣ = ወይቤሎ መልአከ አግዚአብሔር ሑር. ምስለ ኤሉ ሰብክ ወበሕቱ ቃለ ዛእቤለክ ኪያሁ ተወቀብ ለነቢብ ወሖረ ዘለፍም ምስለ መላእክተ በላቅ።",
    ),
    (
        14,
        5,
        "ወስበ ሰምዐ ባላቅ ከመ መጽአ በለዓም ወዕኣ ወተቱ በሎ ውስተ ሀገረ ሞአብ እንተ ደወለ ጾርናን አንተ ህለ ወት ውስተ አሐዱ ኀግብር አምደወሎሙ = ወሬቤሎ በላቅ ለበለዓም አከት ለአክኩ “ቤክ ይጺጸው ዑክ ለምንት አ መጃሕክ ሣቤየ ኣምኢ ክህልት አክብ ሮተክ።",
    ),
    (
        14,
        6,
        "1 8 ah aR aL ii [i f | ደ [iy [UN ወይቤሎ በለዓም ለበላቅ ናሁ መጻአሇ ኀቤከ ይእዚኒ ኢይክል ነቢበ ቃል ምንተ፤ ዳፀሙ ዘወደየ አማዚአብሑር ውስተ አፉየ ወኪያሆሁ ኣትዓቀብ ለነቢብ።",
    ),
    (14, 7, "ወሐረ በለኝም ምስለ በላቅ ወቦኢ. ውስተ ህገረ ንድቅ።"),
    (
        14,
        8,
        "ወጠብሐ በላቅ ጸበግዐ ወአልሕምተ ወፈነወ ለበለ ዓም ወለመላእክት እለ ምክሌሁ = ወክነ ለበ ጸብሐ ነሥዖ በላቅ ለበለዓም ወአዕረን ውስተ ትእምርተ በላአል ፡ ወአርአዮ እምህየ አሐደ ኃብረ አም ቋቁዝብ።",
    ),
    (14, 9, "ወይቤሎ በለዓም ለበላቅ ንድቅ .ለ.ተ ዝየ ሰብቦተ መሣውኝተ ወአስተትዳሉ ሊተ ዝየ ሰብዓተ አልሕምተ ወሰ ብኝጓተ አባግዐ።"),
    (14, 10, "ወገብረ ባላቅ በከመ ይቤሎ በለዓም ወአፅረገ ላሕመ ወበግዐ ላዕለ ምሥዋዕ።"),
    (14, 11, "ወይቤሎ በለዓም ለባላቅ ቁም ግበ መሥዋዕት ወጸ ሕውር እመ የስተርእየኒ እግዚአብሔር ቅድሜየ ወቃለ ዘአስተርክየኒ አየድዐክ ወቁመ በላቅ ሣበ መሥዋዕቱ።"),
    (
        14,
        12,
        "ወበለዓምስ ሐደ ይሰአሎ ለእግዚአብሔር ወሖረ ርቱ ወአስተርአጸዮ አግዚሾቑሔር ለበለዓም ( ወይቤሎ በለዓም ለእግዚጸብሔር ናሁ አስተዳለውኩ ለከ ሰብዓተ መሣው ዓተ ወአዕረጉ ለክ ሰብዓተ አልሕምተ ወሰብዓተ አኣቫግዐ ላዕለ ምሥዋዕ = | ወወደየ አግዚአብሔር ቃለ ውስተ አፉሁ ለበለዓም ፡ ወይቤሎ ግባእ ጋበ በላዋ ወከመዝ በል።",
    ),
    (14, 13, "ወገብአ ኀቤሁ ወረከቦ ይቀውም “ኃበ መሥዋዕቱ ወዙ ሎሙ መላአክተ ሞአብ ምስሌዑ ፡ ወመጽክ መንፈስ እግ ዚክብሔር ላዕሌሁ ምስለ ነገር።"),
    (
        14,
        14,
        "' ወይቤ እመስጴጦምያ ጸውክ፤ በላቅ ንገ-ሠ ሞአብ አም ደወለ ጽባሕ አንዘ ይብል ፡ ነዐ ርግሞ ሊተ ለያዕቆብ ወነዓ ጸክሎ ሲተ ለክስ ራኤል = ምንተ ኣጴኣል ዘአግዚአብሔር ኢጸአለ ወምንተ. እረ . ግም ዘኣአግዚጸብሔር ኢረገመ።",
    ),
    (
        14,
        15,
        "እስመ አምአርእስተ ኣድበር እሬእዮ ፡ ወእም አውግር የኢትዮጵያ ኦርቶዶክስ ተኖዋሕዶ ቤት FEE NW ) አሪት ዘጐልሑ , a5 iy fs ~-እቋብዎ- ዳሁ-ሕዝብ -ዝዘበሕቲቱ የሣድር. ወእት ለቀ |- - ውስተ አሕዛብ።",
    ),
    (14, 16, "መኑ የጽምሮ ለዘር ያዕቁብ ወመኑ ይሕልቁ ለሕዝበ አስራኤል ወትመሙት ነፍስየ ምስለ-ነፍፀሙ ለጻድቃን ወይ ኩን ዘርእየ. ከመ ዘርአሙመ- ለእሉ።"),
    (14, 17, "ወይቤሎ በላቅ ለበለዓም ለምንት ረፅይከኒ ከመዝ አ ኮኑ ትርግም ሊተ ፀርየ ጸዋዕኩከ ወናሁ በርኮ ባረክ።"),
    (
        14,
        18,
        "ወይቤሎ በለዓም ለበላቅ አክኑ ዙሎ ቃለ ዘወደየ አግ ዚአብሔር ውስተ አፉየ ቢያሁ እትዓቀብ ለነቢብ = ይቤሎ በላቅ ነዓ ዓዲ ምስሌየ ካልክ መክነ ጎበ ኢ.ት Ir ‘ሎሙ መላእክተ ሞአብ ምስሌሁ ፡ ወይቤሎ በላቁ ለበለ '\" ዓም ፡ ምንተ ይቤ እግዛ አብሔር ምስለ ነንር = ሬይሕዮመሙ በሀዕየ ሣኣንበል አሐዱ “ዳብር ዛትሬኢ እምኔሆሙ ወችጵሎሙስ ኢትሬኣ. ወርግሞሙ ሊተ በህየ።",
    ),
    (14, 19, ". ወነሥኣ ወኣፆዶ ወውስተ ንዳም ውስተ ርእሳ ደብር ዘውቅሮ ወነደቀ ሰብዓተ ምሥዋዓተ ወአዕረኘ ላሕመ ወበ ግዐ ላዕለ ምሥዋዕ።"),
    (14, 20, ". ወይቤሎ ከለኝም ለባላቅ ቁም “በ ምሥቁዕ፡ ወአንሰ አሐውር አሰአሎ ለአግዚአብሔር።"),
    (
        14,
        21,
        "ወተራከበ እግዚአብሔር ለበለዓም ወወደየ ቃለ ውስተ ጸታሁ ወይቤሎ. ግቧእ ጎበ ባላቅ ወክመዝ.-በል = ወኘብአ ኀቤሁ ወረከቤ ይቀውም ሣበ ምሥዋዕ ወዙ ወይቤ ተንሥአ ወስማፅ ወአፅ ሥ እ በላቅ ወልደ ስፎር።",
    ),
    (14, 22, "አኮ ክመ ሰብአ ዘይትዬዋህ እግዚኣብሔር ወሕክ ከመ እጓሉ አመሕያው ዘPትሜአክ አንተሰ ትቤ እ.ይገብር. ወኢይነብበቷ ወኢያበጽሳሕ i ) ናሁ ለባርኮ መጻእኩ አባርክ።"),
    (14, 23, "ወአ-ይትመያጥ « አልበ ፃማ ውስጥ ያፅቁቆኻኽ ወኢያስ ተርኢ ሕማም ላዕ አስራኤል ፡ እግዚአብሔር አምላኩ ምስሌሁ ወክብረ መላ ኣቫት ሎቱ።"),
    (14, 24, "እግአብሔር ዘአውዕ።"),
    (
        14,
        25,
        "እምብሔረ ግብጽ ከመ ክብረ ዘኣሐዱ ቀርኑ = ጸልቦ ሰገል ውስተ ያፅቋብ ወአልቦ መቅስም' በውስት ኣስራኤል ወለለመዋዕሊሁሆ ይትበህሄል ለያዕቆብ ወለኣስራ 'ጴል ምንተ ይገብር ኣግዚአብሔር።",
    ),
    (14, 26, "ናሁ ሕዝብ ዘይትነሣእ ከመ እጓለ ኣንበሳ ወይጥሕር ዝመ እንበባ ዘኢይነውም. አስከ ይበልዕ ዛነፀወ ወይሰቲ ደመ ዘቀተስለ።"),
    (14, 27, "| መወይቤሎ በላቅ ለበለዓም ኳ. መርገመ ትረግቁvሙ ሊት ወኢ በርክ ትበርክሙ።"),
    (
        14,
        28,
        ". ወአውሥአ በለዓም ለበላቁ ወይቤሎ ኢይቤለከኑ እንዝ ክብል ቃለ ዘይቤላሂ አግቪልብሔር. ኪያሁ አንብር = ወነሥአ በላሕ ለበለዓም ውስ ተ ርእሰ ፌጎር ዛየፀውድ ‘ውስት ንገዳም * - - ወይቤሎ በለዓም ለበላ ንጅቅ ሊተ ዝየ ሰብዓተ ምመሥዋኝት ፡ ወአስተዳሉ ሊተ ዝየ ሰብኝተ አልሕምተ ወሰ ብዓተ አጻግዕፀ።",
    ),
    (
        14,
        29,
        "ወገብረ በላቅ ባክመ ይቤሎ በለዓም ወአዕረ፣ ላመ መበግሀፀ ላዕለ ምሥዋዕ = ወፀ ርእየ በለዓም ከመ ሠናይ ውእቱ ቅድ አማዚ ጸብሔኗ በርክ ስእል ፡ እ.ሐሪ በኸመ ያልም ድ መኝ | ጸረ ቅድሜሁ ለጸስትቃስዕ።",
    ),
    (
        14,
        30,
        'ወሜጠ ንጻ መንንለ ምሥራቅ ጃኝ oH 88 ፳፪ 8 የኢትዮጵያ ኦርቶዶክስ ተዋሕዶ ቬት አሪቲ ልቀ | AEE nn የኢትዮጵያ አርዯቸዶክስ. ተዳ ሕዶ ffi [28 አሪት ዘጎጐልዀ፡ ወአልክለ አዕይንቲሁ ወርክዮሙ ስክሾራኤል አንጃ ዴማ ዕዙ በበሕዛቢሆሙ ወመጽአ ላፅፀሌሁ መንፈሰ እአግዚአብ ሔር ምስስ ነገር = ወይቤ በለዓም ወልደ ቤዖር ብእሲ. ራትs ይቤ ዘይሬጺ ራክየ አምእግዚአብሔር ዘከሙታት አዕይንቲሁ አንዝ ይንውም = አፎ ሠናይ አብያቲክ ያዕቋብ ወተኝይኒከ አስራኤል = ከመ አእቁም ዘይጴልሎ ወከመ ገነት ዘሣበ "ፈለግ ወከመ ትዕይንት ዘተክለ እግዚአብሔር ወከመ አርዝ ዘኘበ ማይ።',
    ),
    (14, 31, "ወይወጽእ ብአሲ እምዛርኤኡ ወይቂ፤ ብዙግነ አሕዛበ . ወትትሌወል እም አጋማ መንግሥቴ ወተ ዐቢ።"),
    (
        14,
        32,
        "ወእግዚአብሔር መርሖ አምግብጽ ከመ ክብረ ዝጸሐዱ ቁርኑ ውእቱ ሱቁ ወይ በልፆያሙ ለአሕዛብ ፀሩ ወስተ ና ጕፅ ስብሖሙ ወይነድሙ በክሕፃሁ ለፀሩ = ይሰክብ ወየፀርፍ ከመ አንበሳ ወከመ አጓለ አንበሳ መነ ያየነቅሐ።",
    ),
    (14, 33, "ኣለ ይበርኩክ ቡሩክ፥ ይኩኑ ማሃ ይኩኑ።"),
    (
        14,
        34,
        "ወተም በ በላቅ -ላዕለ በለዓም ወክስተጣፍሐ አዴዌዊሁ ! ወይቤሎ በላቅ ለበለዓም ከመ ትርግሞሙ ሊተ ለጺጸላአትየ ጸዋዕኩክ ወናሁ በርኮ ትባርክ ሣልስከ ዝንቱ = ወይክዚቷ እቱ ቤታክ አቤ ከመ አክብሮ አክብርክ፡ ወይአዙሰ ኢወሀበክ እግዚአብሔር መብረ = መኣስ ይረግሙክ ርን ወይቤሎ በለዓም ለባላቅ አኮኑ ለወኝንልት ከኒ እለ ለአከ - ጓቤየ አቤሎሙ እንሃ አብል ፡ ለኣመ ወሀበ በላቁ ወርቁ ወብሩረ ምልክ ዝንቱ ቤት ኣ.ይክል ተዐድዎ ቃለ እግዚ አብሔር ከመ እግበር ሠናየ አው እኩየ እምሣቤየ ሁሎ ዘይቤ ለ፤ እግዚአብሔር ኪያሁ እብል።",
    ),
    (
        14,
        35,
        "ወይእዜኒ ናሁ አክቱ ቤትየ ፡ ወነዐ አይድፅክ ዘይገብሩ እሉ ሕዝብ ላዕለ ሕዝብክ በደኃሪ መዋዕል ምስለ ነገር = ወይቤ በለዓም ወልደ ቤpር ብእ. 'ራትፅ ይቤ ዘይሬአ.።",
    ),
    (14, 36, "ወይበምፅ ቃለ እግዚአብሔር ዘየአምር መዝራስቶ ለልዑል ወርአየ ራኣየ እግዚአብሔር ክሠ.ታት' አፅይ ንቱሁ እንዘ ይነውም እሬእአዮ።"),
    (
        14,
        37,
        "ወአክ ይእዙ:አስተበዕፆዎ ወእክኮ ዛይነውም ወይቀርብ ፡ ይሠርቅ ኮከብ ኣአምያዕቆብ ወይትነሣክ ክም አስራኤል ወያ .. ጠፍጾአሙ ለመላእከተ ሞእብ ወደጽውጀሙ ለዙሎሙ ደቂቅ ሴች = ወይከውናኖ ኤዶም ርከቶ ወይከውና ርስቶ ኤሳው ፀሩ # fe Ll) Ly) Uy ly) Y= Ly le Ly ኦሪት -ዘ' A ወእስራኤልዛ ገብረ በኀይል።",
    ),
    (
        14,
        38,
        "መወይችነሣክኣ ብእሲ ኃያል ኣምያፅቆብ፡ ወያጠፍአሙ ለእብ ድሣኑ ኣም ህገር = ወርኣዪሙ ለእማሌቅ ምስለ ነገር ወይቤ ቀዳሚሁ ለኣ ሕዛብ አማሌቅ ወይጠፍኣ ዘርአሙ = ወርእዮሙ ስቄ2ዎን ም።",
    ),
    (
        14,
        39,
        "ስስ ነገር ወይሠ ጽ ነፀተ አሽ ይክ ፡ ወለኣመሂ ውስተ ኰኵኩሕ ኣንበርክ እጐሊከ = ወሳአመኒ፡ ክነ ለቤያሮ እለ ጕሕሉቱ t, አዕር ይው ወክ a ወርኣዮ ለኣኝሣ ምስለ ነገር ወይቤ Lay መታ የሓዬ 3 ጸመ ይገብሮ እግዚአብሔር ለዝንቱ = ወይደወዕኣ እምአዴሆሙ ለተጥያዎን ወenክዩ nec ብዕብራውያን፡ iE የኣክዩ ብአሰር ወእሙንቱሰ ዓረ ይጠፍ።",
    ),
    (14, 40, "- ወተንሥጳ ቤለዓም ወሖረ ወገብ ውስተ ቤቱ ፣ ወበላ ቅቲ ትወ ቤቶ።"),
    (14, 41, ". መኝዶሯ ኣስራኤል ውስተ ሰዉን ወተገመትኑ ሕዝብ pin, በአወልድ ምጸብ።"),
    (14, 42, 'ወጽውኝሆሙ ውስተ መሥ’ዋፀቱ አማልክቲሆን ወ" ልቡ ሕዝብ መሥዋዕቶች ወሰኘንዱ ለአማልክቲሆን።'),
    (
        14,
        43,
        "ወተፈጾመ እስራል በብዔል ፌጎር ወተምዐ፡ መፀተ አግዚጸጣሔር ላፅለ እስራኤል • \" ወይቤሎ እግዚአብሔር ሰሙዬ ንሥመአሙ ለመላአክት ሕዃብ ወተዛለፎሙ በአንተ ትእዛዙ ለእግዚአብሔር ፀሐ ይኒ ይስል እምቅድመ ,'መንሱተ መፀቱ ለአግዚአብሔር እምአስራሌል።",
    ),
    (14, 44, "ወይቤሎሙ ሙሴ ለሕዝበ አስራኤል ፡ ቀትሉ አሐዱ አሐዱ ክምኒቫሙ 'በብቋ ቤትክሙ ፡ እለ ገብሩ በብቈል ፌንገር።"),
    (
        14,
        45,
        "ወናሆ አሐዱ ብኣሲ እምዴቁቃ አስራሌል መጽአ ወወ በዶ ስክዯሁ ኋቤበ መድፍናዊት በቅድመ ሙሴ ወበቅድመ ኵጨ ተዓይደሆሙ ለደቂቀ . አስራሔል ወኣሙንቱብ ሀለዉ. ድበዃዩ ጎበ ናንተ ዶብተራ ሃመርጨጡል።",
    ),
